import {ToyRoomPhase} from '../../../src/js/toy-room/ToyRoomPhase.js';
import {nearestToyGuide} from '../../../src/js/toy-room/ToyRoomOrientation.js';
const check=(value,message)=>{if(!value)throw Error(message);};
const makeRoom=difficulty=>{const r=new ToyRoomPhase(document.querySelector('canvas'),null,document.querySelector('#feedback'),null,{assets:review.game.assets,bindInputs:false,gameDifficulty:difficulty});r.tutorial.finish();r.introAlpha=0;r.introBannerTimer=0;return r;};
const action=r=>{r.lastActionTime=-Infinity;r.triggerAction();};
export async function audit(){
 const reports=[];
 for(const difficulty of ['NORMAL','EASY']){
  let deliveries=0;
  for(const type of ['teddy','train','robot','bunny','duck','blocks','drum','jack']){
   const r=makeRoom(difficulty),toy=r.toys.find(t=>t.type===type),chest=r.furniture.find(f=>f.id==='toy-chest');
   Object.assign(r.player,{x:toy.x,y:toy.y});action(r);check(r.player.carriedItem===toy,'Coleta inicial de '+type);
   r.update(1);check(r.fairy.targetX===chest.x+chest.w/2&&r.fairy.targetY===chest.y-75,'Fada aponta sobre o baú ao carregar');
   const other=r.toys.find(t=>t!==toy);Object.assign(r.player,{x:other.x,y:other.y});for(let i=0;i<4;i++)action(r);
   check(r.player.carriedItem===toy&&toy.isCarried&&!other.isCarried,'Ação repetida não solta nem troca o brinquedo');r.interaction.updateProximity();check(!r.canInteract,'Outro brinquedo não habilita coleta');
   const restored=makeRoom(difficulty);restored.restore(r.snapshot());restored.update(1);check(restored.player.carriedItem?.id===toy.id&&restored.fairy.targetX===chest.x+chest.w/2,'Save/restore conserva carga e guia para o baú');restored.destroy();
   Object.assign(r.player,{x:chest.x+chest.w/2,y:chest.y+chest.h/2});action(r);check(!r.player.carriedItem&&toy.isOrganized&&r.organizedCount===1,'Entrega libera as mãos');r.update(1);
   const nearest=nearestToyGuide(r.player,r.toys,null);check(r.guideToy===nearest&&r.fairy.targetX===nearest.x&&r.fairy.targetY===nearest.y-105,'Após guardar, fada segue o brinquedo mais próximo');
   Object.assign(r.player,{x:nearest.x,y:nearest.y});action(r);check(r.player.carriedItem===nearest,'Coleta liberada novamente');deliveries++;r.destroy();
  }
  const r=makeRoom(difficulty),toy=r.toys[0];Object.assign(r.player,{x:toy.x,y:toy.y});action(r);check(!r.story.beginInvestigation(),'Investigação espera entregar o brinquedo atual');
  const chest=r.furniture.find(f=>f.id==='toy-chest');Object.assign(r.player,{x:chest.x+chest.w/2,y:chest.y+chest.h/2});action(r);check(r.story.beginInvestigation(),'Investigação começa após entrega');
  let revealed=false;
  for(let i=0;i<30&&r.story.state.investigationStage==='INVESTIGATION';i++){
   r.update(100);if(r.story.state.sword.visible){revealed=true;check(!r.story.canCollectToys,'Espada revelada bloqueia brinquedos');check(r.fairy.x===1360&&r.fairy.y===250,'Fada fixa sobre espada desde a revelação');}
  }
  check(revealed&&r.story.state.investigationStage==='SEEKING_SWORD','Cena completa revela espada');const sword=r.story.state.sword;check(sword.x===1360&&sword.y===330&&r.story.world.isFree(sword,48),'Espada no piso livre à direita do baú, abaixo da janela');check(r.story.world.reachableFloor().some(p=>Math.hypot(p.x-sword.x,p.y-sword.y)<40),'Ponto da espada acessível pelo piso');
  const available=r.toys.find(t=>!t.isOrganized);Object.assign(r.player,{x:available.x,y:available.y});r.interaction.updateProximity();action(r);check(!r.player.carriedItem&&!r.canInteract,'Só a espada fica disponível');
  for(const dt of [1,3,10]){r.update(dt);check(r.fairy.x===sword.x&&r.fairy.y===sword.y-80,'Fada não abandona a espada por outro brinquedo');}
  const restored=makeRoom(difficulty);restored.restore(r.snapshot());restored.update(1);action(restored);check(!restored.player.carriedItem&&!restored.story.canCollectToys&&restored.fairy.x===1360,'Save conserva exclusividade da espada');restored.destroy();
  Object.assign(r.player,{x:1260,y:360});r.cameraX=1280-r.canvas.width/2;r.cameraY=300-r.canvas.height/2;r.render();
  if(difficulty==='NORMAL')window.swordReview=r.canvas.toDataURL().split(',')[1];
  Object.assign(r.player,{x:sword.x,y:sword.y});r.story.updateAfterMovement();check(r.story.state.investigationStage==='PICKUP'&&!sword.visible&&!r.player.carriedItem,'Espada recolhida por aproximação');r.story.update(300);check(r.story.swordEquipped&&!r.story.canCollectToys,'Espada equipada mantém bloqueio de brinquedos');
  reports.push({difficulty,deliveries,sword:{x:sword.x,y:sword.y},revealed});r.destroy();
 }
 return reports;
}
